#include <stdio.h>

#define MAX 5

int queue[MAX];
int front = 0, rear = 0;

void enqueue(int value) {
    if (rear == MAX) {
        printf("Queue full\n");
        return;
    }
    queue[rear++] = value;
}

int dequeue() {
    if (front == rear) {
        printf("Queue empty\n");
        return -1;
    }
    return queue[front++];
}

int main() {
    enqueue(1);
    enqueue(2);
    enqueue(3);
    printf("%d\n", dequeue());
    printf("%d\n", dequeue());
    enqueue(4);
    printf("%d\n", dequeue());
    printf("%d\n", dequeue());
    return 0;
}
